#include <iostream>
#include <memory>
#include <map>
#include <vector>
#include <functional>
struct SignalState { int next = 1; std::map<int, std::function<void()>> handlers; };
class Subscription {
  std::weak_ptr<SignalState> state_; int id_;
public:
  Subscription(std::shared_ptr<SignalState> state, int id) : state_(state), id_(id) {}
  Subscription(const Subscription&) = delete;
  Subscription& operator=(const Subscription&) = delete;
  ~Subscription() { if (auto s = state_.lock()) s->handlers.erase(id_); }
};
void emit(const std::shared_ptr<SignalState>& s) {
  std::vector<int> ids;
  for (const auto& [id, handler] : s->handlers) ids.push_back(id);
  for (int id : ids) {
    auto it = s->handlers.find(id);
    if (it != s->handlers.end()) { auto handler = it->second; if (handler) handler(); }
  }
}
